"""research#658 item 1e: the inclusion holds for every subgroup generated by reflections and transvections.

Item 1e is Gamma_Co <= ker(rho_{T_Co}) for the monodromy group of the family of unpolarized Coble
surfaces.  This probe verifies, exactly, that the whole of the subgroup generated by the two kinds of
element that occur as monodromy of a period-domain family lies in ker(rho_{T_Co}):

  * reflections s_d in vectors of square -2, the Picard--Lefschetz monodromy of a (-2)-wall
    (prop:monodromy-contains-root-reflections puts them in the geometric monodromy);
  * Eichler transvections tau_{u,v}(x) = x + (x.u)v - (x.v)u for isotropic u, v of product zero.

Both lie in ker(rho_{T_Co}) for one reason, which the probe checks element by element with the exact
discriminant test: an element g of O(L) acts trivially on A_L = L^v/L exactly when g(x) - x lies in L for
all x in L^v, and for both kinds that difference is manifestly in L --
s_d(x) - x = (x,d)d and tau_{u,v}(x) - x = (x.u)v - (x.v)u, with (x, L) in Z.

So the consequence, which is the reduction of item 1e: if Gamma_Co is generated by reflections in
-2-vectors and by Eichler transvections -- equivalently if the reflective subgroup is everything, the
index [Gamma_Co : W(T_Co)] being 1 -- then Gamma_Co lies in the discriminant kernel and, with the sign of
lem:monodromy-is-spinor-positive, the Gamma_Co form of thm:coble-strong-lifting holds.  That index is
open: it is the question of @qst:gamma-co-generators and @prob:coxeter-completeness.

A control is run too: the swap of the two isotropic generators of U(2), which is an isometry of T_Co
fixing nothing relevant, acts NON-trivially on A_{T_Co} -- so the test discriminates, and the conclusion
above is not vacuous.

Usage: python3 computations/reports/coble_658-reflective-generation-probe.py
"""

from __future__ import annotations

from fractions import Fraction as F
from itertools import product


def e8_cartan():
    c = [[0] * 8 for _ in range(8)]
    for i in range(8):
        c[i][i] = 2
    for i in range(6):
        c[i][i + 1] = c[i + 1][i] = -1
    c[2][7] = c[7][2] = -1
    return c


def block_diagonal(blocks):
    n = sum(len(b) for b in blocks)
    g = [[0] * n for _ in range(n)]
    off = 0
    for b in blocks:
        for i in range(len(b)):
            for j in range(len(b)):
                g[off + i][off + j] = b[i][j]
        off += len(b)
    return g


U = [[0, 1], [1, 0]]
G = block_diagonal([[[2]], [[2 * x for x in row] for row in U],
                    [[-2 * x for x in row] for row in e8_cartan()]])     # T_Co, rank 11
N = len(G)


def mv(m, v):
    return [sum(m[i][j] * v[j] for j in range(len(v))) for i in range(len(m))]


def dot(x, y):
    return sum(x[i] * G[i][j] * y[j] for i in range(N) for j in range(N))


def transpose(m):
    return [[m[j][i] for j in range(len(m))] for i in range(len(m[0]))]


def matmul(a, b):
    return [[sum(a[i][k] * b[k][j] for k in range(len(b))) for j in range(len(b[0]))]
            for i in range(len(a))]


def inverse(m):
    n = len(m)
    a = [[F(m[i][j]) for j in range(n)] + [F(int(i == j)) for j in range(n)] for i in range(n)]
    for col in range(n):
        piv = next(r for r in range(col, n) if a[r][col] != 0)
        a[col], a[piv] = a[piv], a[col]
        pv = a[col][col]
        a[col] = [x / pv for x in a[col]]
        for r in range(n):
            if r != col and a[r][col] != 0:
                f = a[r][col]
                a[r] = [x - f * y for x, y in zip(a[r], a[col])]
    return [row[n:] for row in a]


GINV = inverse(G)


def is_integral(m):
    return all(getattr(x, "denominator", 1) == 1 for row in m for x in row)


def is_isometry(m):
    return is_integral(m) and matmul(transpose(m), matmul(G, m)) == G


def discriminant_trivial(m):
    """g acts trivially on A = Z^n/(G Z^n) iff g(y) - y in Z^n for the generators y = G^{-1} e_i."""
    for i in range(N):
        y = [F(0)] * N
        y[i] = F(1)
        y = mv(GINV, y)
        z = mv(m, y)
        if any((a - b).denominator != 1 for a, b in zip(z, y)):
            return False
    return True


def reflection(v):
    gv = mv(G, v)
    out = [[0] * N for _ in range(N)]
    for j in range(N):
        c = gv[j]
        for i in range(N):
            out[i][j] = (1 if i == j else 0) + c * v[i]
    return out


def transvection(u, v):
    gu, gv = mv(G, u), mv(G, v)
    out = [[0] * N for _ in range(N)]
    for j in range(N):
        e = [0] * N
        e[j] = 1
        a = sum(e[i] * gu[i] for i in range(N))
        b = sum(e[i] * gv[i] for i in range(N))
        for i in range(N):
            out[i][j] = e[i] + a * v[i] - b * u[i]
    return out


def e8_roots():
    cartan = e8_cartan()
    out = []
    for x in product(range(-2, 3), repeat=8):
        if sum(x[i] * cartan[i][j] * x[j] for i in range(8) for j in range(8)) == 2:
            out.append(x)
    return out


E8_ROOTS = e8_roots()


def short_vectors(square):
    """Vectors of the given square with h, e', f' in [-2,2] and E8(2)-part 0, rho, or 2*rho."""
    out = set()
    # the E8(2) block is -2*Cartan, so its roots (square -4) are the Cartan roots, and their doubles
    # have square -16; both are needed, since 2a^2 + 4bc + y^2 = -2 has solutions with each.
    tails = ([[0] * 8]
             + [list(rho) for rho in E8_ROOTS]
             + [[2 * t for t in rho] for rho in E8_ROOTS])
    for a, b, c in product(range(-2, 3), repeat=3):
        for tail in tails:
            v = [a, b, c] + tail
            if any(v) and dot(v, v) == square:
                out.add(tuple(v))
    return sorted(out)


def main():
    print("T_Co = <2> + U(2) + E8(2), rank %d" % N)

    roots = short_vectors(-2)
    print("(-2)-vectors with small coefficients: %d" % len(roots))
    bad = [r for r in roots if not discriminant_trivial(reflection(list(r)))]
    print("  reflections in them: all isometries %s; acting trivially on A_{T_Co}: %d of %d"
          % (all(is_isometry(reflection(list(r))) for r in roots), len(roots) - len(bad), len(roots)))
    assert not bad

    isotropic = short_vectors(0)[:200]
    print("isotropic vectors with small coefficients: %d" % len(isotropic))
    tried = 0
    bad = 0
    for u in isotropic:
        for v in isotropic:
            if dot(list(u), list(v)) != 0:
                continue
            g = transvection(list(u), list(v))
            if not is_isometry(g):
                continue
            tried += 1
            if not discriminant_trivial(g):
                bad += 1
    print("  transvections tau_{u,v} with u.v = 0: %d examined; acting trivially on A_{T_Co}: %d of %d"
          % (tried, tried - bad, tried))
    assert bad == 0

    products = 0
    bad = 0
    for r in roots[:10]:
        S = reflection(list(r))
        for u in isotropic[:10]:
            for v in isotropic[:10]:
                if dot(list(u), list(v)) != 0:
                    continue
                g = matmul(transvection(list(u), list(v)), S)
                if not is_isometry(g):
                    continue
                products += 1
                if not discriminant_trivial(g):
                    bad += 1
    print("  products s_d o tau_{u,v}: %d examined; trivial on A_{T_Co}: %d of %d"
          % (products, products - bad, products))
    assert bad == 0

    swap = [[int(i == j) for j in range(N)] for i in range(N)]
    swap[1][1] = swap[2][2] = 0
    swap[1][2] = swap[2][1] = 1
    print()
    print("control, the swap e' <-> f' of the U(2) block: isometry %s, acts trivially on A_{T_Co} %s"
          % (is_isometry(swap), discriminant_trivial(swap)))
    assert is_isometry(swap) and not discriminant_trivial(swap)
    print()
    print("consequence: ker(rho_{T_Co}) contains the subgroup generated by the reflections in")
    print("(-2)-vectors and the Eichler transvections -- every generator, and the products tested above,")
    print("satisfy g(x) - x in T_Co for x in the dual, which is the condition.")
    print("verdict: item 1e holds for every subgroup generated by these elements; it therefore holds for")
    print("  Gamma_Co as soon as Gamma_Co is so generated, i.e. as soon as [Gamma_Co : W(T_Co)] = 1.")
    print("  That index is open: @qst:gamma-co-generators and @prob:coxeter-completeness.")


if __name__ == "__main__":
    main()
